import React, { Component } from 'react';
import {
    CButton, CCard, CCardBody, CCol, CContainer, CInput, CInputGroup,
    CInputGroupAppend, CInputGroupPrepend, CInputGroupText, CRow
} from '@coreui/react';
import MaterialReactTable from 'material-react-table';
import {
    requestHeaderPOSTWithAuth,
    requestHeaderPUTWithAuth,
    requestHeaderDELETEWithAuth,
} from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

import Select from 'react-select';

const FILE_NAME = "MediaDataCreator.js";

const API_BASE = BACKEND_NEXUS_APP_BASE_URL + '/v1/media-data-creator';

const emptyForm = {
    id: null,          // null => create mode, non-null => edit mode
    name: '',
    link: '',
    description: '',
    platformUniqueId: '',  // optional whole number
    tenantId: '',
};

class MediaDataCreator extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            mediaList: [],
            // tenant dropdown options
            tenants: [],
            tenantsLoadError: false,
            // free-text search across name / link / description + pagination
            searchTerm: '',
            page: 1,
            size: 10,
            totalPages: 0,
            totalElements: 0,
            // add / edit form
            form: { ...emptyForm },
            formError: null,
            // modals
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "Media Data Creator";
        this.fetchTenants();
        this.loadAll();
    }

    // ---------- tenants (searchable dropdown) ----------

    fetchTenants = () => {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/tenants';
        const reqData = { page: 1, size: 100 };

        fetch(url, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchTenants", "SUCCESS", "result", result);
            const content = (result && result.data && result.data.content) || [];
            this.setState({ tenants: content, tenantsLoadError: false });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchTenants", "ERROR", "error", error);
            this.setState({ tenantsLoadError: true });
        });
    }

    // Build react-select options from the fetched tenants list.
    tenantOptions = () => this.state.tenants.map(t => ({
        value: String(t.id),
        label: t.urn ? `${t.name} (${t.urn})` : `${t.name} [#${t.id}]`,
    }));

    // ---------- helpers ----------

    isEditing = () => this.state.form.id != null;

    nullIfBlank = (value) => {
        const trimmed = (value || '').trim();
        return trimmed === '' ? null : trimmed;
    }

    // ---------- clipboard ----------

    // Paste clipboard text into a form field.
    pasteFromClipboard = (field) => {
        if (!navigator.clipboard || !navigator.clipboard.readText) {
            this.setState({ failureModalVisible: true });
            return;
        }
        navigator.clipboard.readText()
            .then(text => {
                Logger(FILE_NAME, "pasteFromClipboard", field, "text", text);
                this.handleFormChange(field, text);
            })
            .catch(error => {
                Logger(FILE_NAME, "pasteFromClipboard", field, "error", error);
                this.setState({ failureModalVisible: true });
            });
    }

    // Copy an arbitrary value to the clipboard.
    copyToClipboard = (value) => {
        const text = value == null ? '' : String(value);
        if (!navigator.clipboard || !navigator.clipboard.writeText) {
            this.setState({ failureModalVisible: true });
            return;
        }
        navigator.clipboard.writeText(text)
            .then(() => Logger(FILE_NAME, "copyToClipboard", "SUCCESS", "text", text))
            .catch(error => {
                Logger(FILE_NAME, "copyToClipboard", "ERROR", "error", error);
                this.setState({ failureModalVisible: true });
            });
    }

    handleUnauthorized = () => {
        this.setState({ loadingModalVisible: false, failureModalVisible: true });
        setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
    }

    // ---------- read: list + search ----------

    // Paginated free-text search (POST /search with PaginatedSearchRequest).
    // A blank/short term makes the backend return all rows, paginated.
    fetchList = () => {
        const { page, size, searchTerm } = this.state;
        const userData = getUserDataFromLocalStorage();
        const url = API_BASE + '/search';
        const reqData = { page, size, search: searchTerm ? searchTerm.trim() : null };

        Logger(FILE_NAME, "fetchList", "REQUEST", "reqData", reqData);
        this.setState({ isLoaded: false });

        fetch(url, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) return this.handleUnauthorized();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchList", "RESULT", "result", result);
            const pageData = (result && result.data) || {};
            this.setState({
                isLoaded: true,
                mediaList: pageData.content || [],
                totalPages: pageData.totalPages || 0,
                totalElements: pageData.totalElements != null ? pageData.totalElements : 0,
            });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchList", "ERROR", "error", error);
            this.setState({ isLoaded: true, failureModalVisible: true });
        });
    }

    // "List all / refresh" — reset to page 1 with an empty search term.
    loadAll = () => {
        this.setState({ searchTerm: '', page: 1 }, () => this.fetchList());
    }

    handleSearch = (event) => {
        if (event) event.preventDefault();
        this.setState({ page: 1 }, () => this.fetchList());
    }

    handlePrevPage = () => {
        if (this.state.page > 1) {
            this.setState({ page: this.state.page - 1 }, () => this.fetchList());
        }
    }

    handleNextPage = () => {
        if (this.state.page < this.state.totalPages) {
            this.setState({ page: this.state.page + 1 }, () => this.fetchList());
        }
    }

    // ---------- create / update ----------

    handleFormChange = (field, value) => {
        this.setState(prevState => ({ form: { ...prevState.form, [field]: value } }));
    }

    resetForm = () => {
        this.setState({ form: { ...emptyForm }, formError: null });
    }

    startEditing = (item) => {
        this.setState({
            form: {
                id: item.id,
                name: item.name || '',
                link: item.link || '',
                description: item.description || '',
                platformUniqueId: (item.metadata && item.metadata.platformUniqueId != null) ? String(item.metadata.platformUniqueId) : '',
                tenantId: item.tenantId != null ? String(item.tenantId) : '',
            }
        });
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    handleSubmit = (event) => {
        event.preventDefault();
        const { form } = this.state;

        const name = (form.name || '').trim();
        // tenantId is optional: when left blank the backend derives it from the link
        // (via the tenant's base_domains match).
        const tenantIdRaw = form.tenantId == null ? '' : String(form.tenantId).trim();
        if (name === '') {
            this.setState({ formError: 'Name is required.' });
            return;
        }

        const platformUniqueIdRaw = form.platformUniqueId == null ? '' : String(form.platformUniqueId).trim();
        let platformUniqueId = null;
        if (platformUniqueIdRaw !== '') {
            if (!/^-?\d+$/.test(platformUniqueIdRaw)) {
                this.setState({ formError: 'Platform Unique ID must be a whole number.' });
                return;
            }
            platformUniqueId = Number(platformUniqueIdRaw);
        }

        const payload = {
            name,
            link: this.nullIfBlank(form.link),
            description: this.nullIfBlank(form.description),
            // platformUniqueId lives inside the MediaDataCreator.metadata jsonb object (MediaDataCreatorMetadata) on the backend.
            metadata: { platformUniqueId },
            tenantId: tenantIdRaw === '' ? null : Number(tenantIdRaw),
        };

        const editing = this.isEditing();
        let url = API_BASE + '/save';
        let requestOptions = requestHeaderPOSTWithAuth(JSON.stringify(payload), getUserDataFromLocalStorage().authToken);
        if (editing) {
            payload.id = form.id;
            url = API_BASE + '/update';
            requestOptions = requestHeaderPUTWithAuth(JSON.stringify(payload), getUserDataFromLocalStorage().authToken);
        }

        Logger(FILE_NAME, "handleSubmit", editing ? "UPDATE" : "CREATE", "request", { url, payload });
        this.setState({ formError: null, loadingModalVisible: true, loadingModalState: 0 });

        fetch(url, requestOptions)
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) return this.handleUnauthorized();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleSubmit", "RESULT", "result", result);
            if (!result) return;
            if (result.code === 1001) {
                // success
                this.setState({ loadingModalState: 1 });
                setTimeout(() => {
                    this.setState({ loadingModalVisible: false, loadingModalState: 0 });
                    this.resetForm();
                    this.loadAll();
                }, 600);
            } else {
                // backend business error (e.g. duplicate name/link, or tenant could not be resolved
                // from the link) — surface the exact backend message in the form error banner and
                // scroll it into view so it isn't missed.
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    formError: result.message || 'Save failed (backend rejected the request).',
                });
                window.scrollTo({ top: 0, behavior: 'smooth' });
            }
        })
        .catch(error => {
            Logger(FILE_NAME, "handleSubmit", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    // ---------- delete ----------

    handleDelete = (item) => {
        if (!window.confirm('Delete media data creator #' + item.id + '?')) return;

        const userData = getUserDataFromLocalStorage();
        const url = API_BASE + '/' + item.id;

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        fetch(url, requestHeaderDELETEWithAuth(null, userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) return this.handleUnauthorized();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleDelete", "SUCCESS", "result", result);
            this.setState({ loadingModalState: 1 });
            setTimeout(() => {
                this.setState({ loadingModalVisible: false, loadingModalState: 0 });
                // if we were editing the row we just deleted, clear the form
                if (this.state.form.id === item.id) this.resetForm();
                this.loadAll();
            }, 600);
        })
        .catch(error => {
            Logger(FILE_NAME, "handleDelete", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    // ---------- render ----------

    // Small inline "copy to clipboard" button used in list cells.
    renderCopyButton = (value) => (
        <CButton
            color="link"
            size="sm"
            className="p-0 ml-1"
            title="Copy to clipboard"
            style={{ verticalAlign: 'baseline' }}
            onClick={() => this.copyToClipboard(value)}
        >
            📋
        </CButton>
    )

    // MaterialReactTable column definitions for the results list.
    // Column order: ID, Actions, then a single combined column holding
    // Name / Link / Description / Tenant / Platform Unique ID.
    getColumns = () => ([
        {
            accessorKey: 'id',
            header: 'ID',
            size: 70,
        },
        {
            accessorKey: 'actions',
            header: 'Actions',
            size: 160,
            enableSorting: false,
            enableColumnFilter: false,
            Cell: ({ row }) => (
                <span style={{ whiteSpace: 'nowrap' }}>
                    <CButton color="primary" size="sm" className="mr-2" onClick={() => this.startEditing(row.original)}>✏️ Edit</CButton>
                    <CButton color="danger" size="sm" onClick={() => this.handleDelete(row.original)}>🗑️ Delete</CButton>
                </span>
            ),
        },
        {
            // Combined Name / Link / Description / Tenant / Platform Unique ID column.
            id: 'details',
            header: 'Details',
            size: 480,
            enableSorting: false,
            Cell: ({ row }) => {
                const { name, link, description, tenantId, metadata } = row.original;
                const platformUniqueId = (metadata && metadata.platformUniqueId != null) ? metadata.platformUniqueId : null;
                return (
                    <div style={{ lineHeight: '1.5' }}>
                        <div>
                            <strong>🧑‍🎨 Name:</strong>{' '}
                            {name ? <>{name}{this.renderCopyButton(name)}</> : '—'}
                        </div>
                        <div>
                            <strong>🔗 Link:</strong>{' '}
                            {link ? (
                                <span style={{ display: 'inline-flex', alignItems: 'center', maxWidth: '440px' }}>
                                    <a href={link} target="_blank" rel="noopener noreferrer" style={{ wordBreak: 'break-all' }}>{link}</a>
                                    {this.renderCopyButton(link)}
                                </span>
                            ) : '—'}
                        </div>
                        <div>
                            <strong>📝 Description:</strong>{' '}
                            {description ? <>{description}{this.renderCopyButton(description)}</> : '—'}
                        </div>
                        <div>
                            <strong>🏢 Tenant:</strong>{' '}
                            {tenantId != null ? <>{this.tenantLabel(tenantId)}{this.renderCopyButton(tenantId)}</> : '—'}
                        </div>
                        <div>
                            <strong>🆔 Platform Unique ID:</strong>{' '}
                            {platformUniqueId != null ? <>{platformUniqueId}{this.renderCopyButton(platformUniqueId)}</> : '—'}
                        </div>
                    </div>
                );
            },
        },
    ])

    // Resolve a tenant id to a readable label (tenant name only; falls back to the raw id).
    tenantLabel = (tenantId) => {
        const match = this.state.tenants.find(t => String(t.id) === String(tenantId));
        if (!match) return tenantId;
        return match.name;
    }

    render() {
        const { isLoaded, mediaList, form, searchTerm } = this.state;
        const editing = this.isEditing();

        return (
            <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                    <h2>🧑‍🎨 Media Data Creators ({this.state.totalElements})</h2>
                    <div style={{ display: 'flex', gap: '8px' }}>
                        <CButton color="primary" onClick={() => this.props.history.push('/media-data')} title="Open Media Data page">🎬 Media Data</CButton>
                        <CButton color="secondary" onClick={this.loadAll} title="Refresh / List all">🔄 List all</CButton>
                    </div>
                </div>

                {this.state.tenantsLoadError && (
                    <div style={{ padding: '12px 16px', marginBottom: '16px', backgroundColor: '#f8d7da', border: '1px solid #f5c6cb', borderRadius: '4px', color: '#721c24' }}>
                        ⚠️ Failed to load tenants list. Please check your connection and <CButton color="link" style={{ padding: 0, color: '#721c24', textDecoration: 'underline' }} onClick={() => this.fetchTenants()}>retry</CButton>.
                    </div>
                )}

                {/* ---------- Add / Edit form ---------- */}
                <CContainer className="mb-4">
                    <CCard className="p-3">
                        <CCardBody>
                            <h4>{editing ? '✏️ Edit Media Data Creator #' + form.id : '➕ Add Media Data Creator'}</h4>
                            <hr />
                            {this.state.formError && (
                                <div style={{ padding: '10px 14px', marginBottom: '14px', backgroundColor: '#f8d7da', border: '1px solid #f5c6cb', borderRadius: '4px', color: '#721c24' }}>
                                    ⚠️ {this.state.formError}
                                </div>
                            )}
                            <form onSubmit={this.handleSubmit}>
                                <CRow>
                                    <CCol md="6">
                                        <label><strong>Link</strong></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>🔗</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="optional https://..."
                                                type="text"
                                                value={form.link}
                                                onChange={(e) => this.handleFormChange('link', e.target.value)}
                                            />
                                            <CInputGroupAppend>
                                                <CButton color="info" type="button" title="Paste from clipboard" onClick={() => this.pasteFromClipboard('link')}>📋</CButton>
                                            </CInputGroupAppend>
                                        </CInputGroup>
                                    </CCol>
                                    <CCol md="6">
                                        <label><strong>Name *</strong></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>🧑‍🎨</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="creator name"
                                                type="text"
                                                value={form.name}
                                                onChange={(e) => this.handleFormChange('name', e.target.value)}
                                                required
                                            />
                                            <CInputGroupAppend>
                                                <CButton color="info" type="button" title="Paste from clipboard" onClick={() => this.pasteFromClipboard('name')}>📋</CButton>
                                            </CInputGroupAppend>
                                        </CInputGroup>
                                    </CCol>
                                </CRow>
                                <CRow>
                                    <CCol md="6">
                                        <label><strong>Tenant</strong> <small style={{ color: '#888' }}>(optional — auto-detected from link)</small></label>
                                        <div className="mb-3">
                                            <Select
                                                value={this.tenantOptions().find(o => o.value === String(form.tenantId)) || null}
                                                onChange={(choice) => this.handleFormChange('tenantId', choice ? choice.value : '')}
                                                options={this.tenantOptions()}
                                                isClearable={true}
                                                placeholder="Search tenant..."
                                                styles={{ control: (base) => ({ ...base, minHeight: '38px' }) }}
                                            />
                                        </div>
                                    </CCol>
                                    <CCol md="6">
                                        <label><strong>Description</strong></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>📝</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="optional"
                                                type="text"
                                                value={form.description}
                                                onChange={(e) => this.handleFormChange('description', e.target.value)}
                                            />
                                            <CInputGroupAppend>
                                                <CButton color="info" type="button" title="Paste from clipboard" onClick={() => this.pasteFromClipboard('description')}>📋</CButton>
                                            </CInputGroupAppend>
                                        </CInputGroup>
                                    </CCol>
                                </CRow>
                                <CRow>
                                    <CCol md="6">
                                        <label><strong>Platform Unique ID</strong> <small style={{ color: '#888' }}>(optional whole number)</small></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>🆔</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="optional whole number"
                                                type="number"
                                                step="1"
                                                value={form.platformUniqueId}
                                                onChange={(e) => this.handleFormChange('platformUniqueId', e.target.value)}
                                            />
                                        </CInputGroup>
                                    </CCol>
                                </CRow>
                                <hr />
                                <div style={{ display: 'flex', gap: '12px' }}>
                                    <CButton color="success" type="submit" className="px-4">
                                        {editing ? '💾 Update' : '➕ Save'}
                                    </CButton>
                                    <CButton color="secondary" type="button" onClick={this.resetForm}>
                                        {editing ? 'Cancel edit' : 'Clear'}
                                    </CButton>
                                </div>
                            </form>
                        </CCardBody>
                    </CCard>
                </CContainer>

                {/* ---------- Search (free-text over name / link / description) ---------- */}
                <CContainer className="mb-3">
                    <CCard className="p-3">
                        <CCardBody>
                            <h5>🔍 Search</h5>
                            <form onSubmit={this.handleSearch}>
                                <CRow className="align-items-end">
                                    <CCol md="9">
                                        <label>Search name, link or description (min 3 chars)</label>
                                        <CInput
                                            type="text"
                                            placeholder="type to search across name / link / description..."
                                            value={searchTerm}
                                            onChange={(e) => this.setState({ searchTerm: e.target.value })}
                                        />
                                    </CCol>
                                    <CCol md="3">
                                        <CButton color="primary" type="submit" className="mr-2">Search</CButton>
                                        <CButton color="secondary" type="button" onClick={this.loadAll}>Clear</CButton>
                                    </CCol>
                                </CRow>
                            </form>
                        </CCardBody>
                    </CCard>
                </CContainer>

                {/* ---------- Results table ---------- */}
                {!isLoaded ? <Loading /> : (
                    <>
                        <MaterialReactTable
                            initialState={{ density: 'compact' }}
                            columns={this.getColumns()}
                            data={mediaList}
                            enablePagination={false}
                            enableEditing={false}
                        />
                        <CContainer className="mt-3">
                            <CRow className="justify-content-center align-items-center">
                                <CCol md="6" className="text-center">
                                    <CButton color="secondary" disabled={this.state.page <= 1} onClick={this.handlePrevPage}>← Prev</CButton>
                                    &nbsp;&nbsp;
                                    <span>
                                        Page <strong>{this.state.page}</strong> of <strong>{this.state.totalPages}</strong>
                                        &nbsp;({this.state.totalElements} total)
                                    </span>
                                    &nbsp;&nbsp;
                                    <CButton color="secondary" disabled={this.state.page >= this.state.totalPages} onClick={this.handleNextPage}>Next →</CButton>
                                </CCol>
                            </CRow>
                        </CContainer>
                    </>
                )}

                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }
}

export default MediaDataCreator;
